<?php
// Uso local una sola vez: abre http://localhost/MiSalud/setup_admin.php
if(!in_array($_SERVER['REMOTE_ADDR']??'',['127.0.0.1','::1'],true)){http_response_code(403);exit('Disponible solo en localhost.');}
require_once __DIR__.'/includes/functions.php';
$exists=row('SELECT id FROM usuarios WHERE rol="admin" LIMIT 1');
$error='';$created=false;
if($_SERVER['REQUEST_METHOD']==='POST'&&!$exists){check_csrf();$mail=trim($_POST['correo']??'');$password=$_POST['password']??'';if(!filter_var($mail,FILTER_VALIDATE_EMAIL)||!valid_pass($password))$error='Ingresa un correo válido y una contraseña fuerte.';else {try{db()->prepare('INSERT INTO usuarios (nombre,apellido_paterno,apellido_materno,correo,telefono,password_hash,rol) VALUES (?,?,?,?,?,?,"admin")')->execute(['Administrador','MiSalud','Sistema',$mail,'0000000000',password_hash($password,PASSWORD_DEFAULT)]);$created=true;}catch(Throwable $e){$error='No se pudo crear el administrador.';}}}
?><!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MiSalud · Configurar administrador</title><link rel="stylesheet" href="<?=url('assets/css/style.css')?>"></head><body class="public-page"><div class="setup-container"><a class="brand" href="<?=url('index.php')?>"><span class="brand-icon">✚</span>Mi<span>Salud</span></a><section class="auth-card"><h2>Administrador inicial</h2><?php if($exists||$created):?><p>Ya existe un administrador. Por seguridad, elimina <code>setup_admin.php</code> del servidor.</p><?php else:?><p>Solo para instalar en tu computadora local. Al terminar, elimina este archivo.</p><?php if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif;?><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Correo del administrador<input type="email" name="correo" required></label><label>Contraseña segura<input type="password" name="password" required minlength="9"></label><button class="btn btn-primary">Crear administrador</button></form><?php endif;?></section></div></body></html>
